import {KEY,content,readState,saveState,emptyState,escapeHTML as e,filterItems,toggleSaved,ensurePlan} from './model.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#detail'),toastBox=document.querySelector('#toast');
let storage;try{storage=window.localStorage;}catch{storage={getItem(){return null;},setItem(){throw Error('Storage unavailable');}};}
let state=readState(storage),page=route(),kind='all',query='',space='all',limit=5,toastTimer,opener,activeDetail=null,undoAction;
const names={discover:'Discover',community:'Community',plan:'My plan',saved:'Saved'};
const paths={search:'M21 21l-5-5 M10.5 18a7.5 7.5 0 1 0 0-15 7.5 7.5 0 0 0 0 15',arrow:'M5 12h14 M13 6l6 6-6 6',up:'M6 18L18 6 M6 6h12v12',bookmark:'M6 3h12v18l-6-4-6 4z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',plan:'M8 3v4 M16 3v4 M3 10h18 M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2',plus:'M12 5v14 M5 12h14',close:'M6 6l12 12 M18 6L6 18',check:'M5 12l4 4L19 6',chat:'M21 11a8 8 0 0 1-8 8H5l-4 3V11a10 10 0 0 1 20 0 M7 10h10 M7 14h6',spark:'M12 2l2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8z',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',compass:'M16 8l-2.5 5.5L8 16l2.5-5.5z M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M9 2h6l1 4 4 1 2 5-3 3 1 4-5 3-3-3-4 1-3-5 2-3-1-4 3-2z',flag:'M5 22V3 M5 3c4-4 9 4 14 0v11c-5 4-10-4-14 0',cap:'M2 9l10-6 10 6-10 6z M6 12v6c4 3 8 3 12 0v-6 M22 9v8',cursor:'M5 3l15 10-7 1-3 7z',chart:'M4 21V13h4v8 M10 21V8h4v13 M16 21V3h4v18',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',back:'M19 12H5 M11 6l-6 6 6 6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.compass}"/></svg>`;
function route(){const value=location.hash.replace('#/','').split('/')[0];return ['discover','community','plan','saved'].includes(value)?value:'discover';}
function persist(){if(!saveState(storage,state))notify('Changes work for this session, but could not be saved on this device.');}
function allItems(){return [...state.posts,...content];}
function item(id){return allItems().find(x=>x.id===id);}
function notify(message,undo){clearTimeout(toastTimer);undoAction=undo;toastBox.innerHTML=`<span>${e(message)}</span>${undo?'<button data-action="undo">Undo</button>':''}`;toastBox.classList.add('toast-visible');toastTimer=setTimeout(()=>{toastBox.classList.remove('toast-visible');undoAction=null;},6500);}
function nav(mobile=false){return Object.entries(names).map(([id,name])=>`<a href="#/${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon({discover:'compass',community:'users',plan:'plan',saved:'bookmark'}[id])}<span>${name}</span>${!mobile&&id==='saved'&&state.saved.length?`<span class="count">${state.saved.length}</span>`:''}</a>`).join('');}
function shell(){rememberFocus();app.innerHTML=`<aside class="sidebar"><a href="#/discover" class="brand"><img src="assets/mark.svg" alt="">find yourjob</a><nav class="nav" aria-label="Main navigation">${nav()}</nav><div class="spaces"><p class="eyebrow">Your spaces</p>${[['design','Product design','cursor'],['data','Data & insights','chart'],['research','User research','chat']].map(([id,label,ic])=>`<button class="space-button ${space===id?'active':''}" data-action="space" data-id="${id}"><span class="space-icon ${id}">${icon(ic)}</span>${label}</button>`).join('')}</div><div class="sidebar-bottom"><div class="profile"><span class="avatar purple">${e(state.name.slice(0,2).toUpperCase())}</span><div><div class="profile-name">${e(state.name)}</div><span class="small muted">A curious explorer</span></div></div><button class="plain settings" data-action="guide" aria-label="Open exploration guide">${icon('spark')}A little guidance</button><button class="plain settings" data-action="settings">${icon('settings')}Settings & your data</button><div class="sidebar-note">A little curiosity goes a long way.</div></div></aside><header class="mobile-header"><a class="brand" href="#/discover"><img src="assets/mark.svg" alt="">find yourjob</a><div style="display:flex;gap:8px"><button class="icon-button" data-action="guide" aria-label="Open exploration guide">${icon('spark')}</button><button class="button" data-action="compose">${icon('plus')}Ask</button></div></header><div class="workspace"><header class="topbar"><div class="breadcrumb">Your next chapter <span>/</span> <b>${names[page]}</b></div><div class="top-actions"><span class="demo-pill">Interactive concept</span><button class="button" data-action="compose">Ask the community ${icon('plus')}</button></div></header><main id="main" tabindex="-1">${page==='plan'?(location.hash.startsWith('#/plan/')?'':planPage()):browsePage()}</main><footer class="footer"><span>Concept preview · Illustrative stories & people · Saved on this device</span><button class="plain" data-action="about">About this preview ↗</button></footer></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav(true)}</nav>`;}
function browsePage(){const intro=page==='discover'?`<section class="hero"><div class="hero-row"><div><p class="eyebrow">Find your job. Find yourself.</p><h1>Find your next chapter<span style="color:var(--accent)">.</span></h1><p>Real stories. Honest answers. Small steps forward.</p></div><p class="hero-note">You don't need to have it<br>all figured out to begin.</p></div></section>`:`<section class="page-head"><p class="eyebrow">${page==='community'?'Good questions open doors':'A collection of possibilities'}</p><h1>${page==='community'?'You’re not figuring it out alone.':'Keep what sparks something.'}</h1><p>${page==='community'?'Ask a question. Share a perspective. Find your people.':'The stories, questions, and small steps you want to return to.'}</p></section>`;return `${intro}<form class="search" id="search-form" role="search">${icon('search')}<input aria-label="Search careers, stories and questions" id="search-input" value="${e(query)}" placeholder="Search careers, stories, or questions..." maxlength="120"><button class="icon-button" aria-label="Search">${icon('arrow')}</button></form>${page==='discover'?`<div class="stage-row"><button class="stage ${state.stage==='first'?'active':''}" aria-pressed="${state.stage==='first'}" data-action="stage" data-id="first">${icon('cap')}Finding my first role</button><button class="stage ${state.stage==='change'?'active':''}" aria-pressed="${state.stage==='change'}" data-action="stage" data-id="change">${icon('compass')}Ready for a change</button></div>`:''}<div class="browse-head"><div class="filters" aria-label="Content type">${(page==='community'?[['all','All discussions'],['question','Questions'],['story','Career stories']]:[['all',page==='saved'?'All saved':'For you'],['story','Career stories'],['question','Questions'],['task','Try a role']]).map(([id,label])=>`<button class="filter ${kind===id?'active':''}" aria-pressed="${kind===id}" data-action="filter" data-id="${id}">${label}</button>`).join('')}</div><span class="result-info">A direction, not a destination</span></div><div id="results">${results()}</div>`;}
function currentItems(){let list=allItems();if(page==='saved')list=list.filter(x=>state.saved.includes(x.id));if(page==='community')list=list.filter(x=>x.kind!=='task');return filterItems(list,{kind,query,stage:page==='discover'?state.stage:'all',space});}
function results(){const filtered=currentItems(),hasFilters=query||space!=='all'||kind!=='all'||(page==='discover'&&state.stage!=='all');if(!filtered.length)return `<div class="empty"><span class="empty-icon">${icon(page==='saved'?'bookmark':'search')}</span><h2>${page==='saved'&&!hasFilters?'Keep a little inspiration.':'A different search might open a new door.'}</h2><p>${page==='saved'&&!hasFilters?'Save a story, question, or task. You’ll find it here whenever you’re ready.':'Try fewer keywords, another direction, or clear your filters to see more possibilities.'}</p><button class="button primary" data-action="${hasFilters?'clear':'discover'}">${hasFilters?'Clear filters':'Explore possibilities'} ${icon('arrow')}</button></div>`;let list=filtered.slice(0,limit);let cards=list.map(card);if(page==='discover'&&!hasFilters&&limit===5)cards.splice(5,0,`<article class="card plan-promo"><div><p class="eyebrow">${icon('flag')} Your next chapter</p><h3>One small step<br>this week.</h3><p class="description">You don’t need a five-year plan.<br>Just somewhere to start.</p></div><a href="#/plan" class="text-link">Make room for what’s next ${icon('arrow')}</a></article>`);return `${hasFilters?`<div class="active-summary" style="margin:0 0 17px"><span>${filtered.length} ${filtered.length===1?'result':'results'}${query?` for “${e(query)}”`:''}${space!=='all'?` · ${e(space)}`:''}</span><button class="text-link" data-action="clear">Clear filters</button></div>`:''}<div class="grid">${cards.join('')}</div>${filtered.length>limit?'<div class="load-row"><button class="button" data-action="more">More possibilities '+icon('arrow')+'</button></div>':''}`;}
function saveButton(x){const saved=state.saved.includes(x.id);return `<button class="icon-button save ${saved?'saved':''}" data-action="save" data-id="${e(x.id)}" aria-label="${saved?'Unsave':'Save'} ${e(x.title)}" aria-pressed="${saved}">${icon('bookmark')}</button>`;}
function card(x){if(x.kind==='story')return `<article class="card story-card">${saveButton(x)}<div class="card-image"><img src="assets/${e(x.image)}" alt="Illustrative ${x.id==='major'?'graduate in a library':'architect in a sunlit studio'}" loading="lazy"><span class="image-type">Career story</span></div><div class="card-body"><button class="card-title" data-action="detail" data-id="${e(x.id)}"><h3>${e(x.title)}</h3></button><p class="card-meta">${e(x.tags)}</p><p class="description">${e(x.excerpt)}</p><div class="card-footer"><span class="author"><span class="avatar">${e(x.initials)}</span>${e(x.author)}</span><button class="text-link" data-action="detail" data-id="${e(x.id)}">Read story ${icon('up')}</button></div></div></article>`;if(x.kind==='task')return `<article class="card task-card ${e(x.space)}">${saveButton(x)}<div class="task-art ${e(x.space)}"><span class="image-type">Try a role</span><span class="art-paper"></span><span class="art-cursor">${icon(x.space==='data'?'chart':x.space==='research'?'chat':'cursor')}</span></div><div class="card-body"><button class="card-title" data-action="detail" data-id="${e(x.id)}"><h3>${e(x.title)}</h3></button><p class="description">${e(x.excerpt)}</p><p class="card-meta">${icon('clock')} ${e(x.tags)}</p><button class="button primary wide" data-action="detail" data-id="${e(x.id)}">Try this task ${icon('arrow')}</button></div></article>`;return `<article class="card question-card">${saveButton(x)}<div class="card-body"><div class="type-row">${icon('chat')} ${x.local?'Your local question':'Community question'}</div><button class="card-title" data-action="detail" data-id="${e(x.id)}"><h3>${e(x.title)}</h3></button><p class="description">${e(x.excerpt.length>170?x.excerpt.slice(0,170)+'…':x.excerpt)}</p><p class="card-meta">${e(x.tags||'Open conversation')}</p><div class="card-footer"><span class="author"><span class="avatar purple">${e(x.initials||'ME')}</span>${e(x.author||state.name)}</span><button class="text-link" data-action="detail" data-id="${e(x.id)}">Join discussion ${icon('arrow')}</button></div></div></article>`;}
function planPage(){const plans=Object.keys(state.plans).map(item).filter(x=>x&&x.kind==='task');if(!plans.length)return '';return `<section aria-label="Saved practice tasks"><h2>Saved practice tasks</h2><div class="plan-list">${plans.map(x=>{const p=ensurePlan(state,x.id),count=(p.checks||[]).filter(Boolean).length;return `<article class="card plan-card ${p.complete?'complete':''}"><span class="plan-icon">${icon(p.complete?'check':'flag')}</span><span class="status ${p.complete?'done':''}" style="position:absolute;right:22px;top:27px">${p.complete?'Reflected & completed':count?'In progress':'Ready when you are'}</span><h3>${e(x.title)}</h3><p class="description">${e(x.excerpt)}</p><div class="progress" role="progressbar" aria-label="Task steps completed" aria-valuemin="0" aria-valuemax="3" aria-valuenow="${count}"><span style="width:${count/3*100}%"></span></div><span class="small muted">${count} of 3 steps explored</span><div class="card-footer"><button class="plain small" data-action="remove-plan" data-id="${x.id}">${icon('trash')}Remove</button><button class="button primary" data-action="work" data-id="${x.id}">${p.complete?'View reflection':count?'Continue':'Start exploring'} ${icon('arrow')}</button></div></article>`;}).join('')}</div></section>`;}
function openModal(body,label){opener=document.activeElement;dialog.innerHTML=`<div class="dialog-top"><span class="eyebrow">${label}</span><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-content">${body}</div>`;if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';dialog.querySelector('h2')?.setAttribute('tabindex','-1');dialog.querySelector('h2')?.focus();}
function replaceModal(body,label){const old=opener;openModal(body,label);opener=old;}
function closeModal(){dialog.close();}
dialog.addEventListener('close',()=>{document.body.style.overflow='';activeDetail=null;const old=opener;requestAnimationFrame(()=>{if(old?.isConnected)old.focus();else document.querySelector('#main')?.focus();});});
function detail(id){const x=item(id);if(!x)return;activeDetail=id;const heading=`<p class="eyebrow">${x.kind==='task'?'A career tryout':e(x.tags||'A community question')}</p><h2 id="dialog-title">${e(x.title)}</h2><p class="intro">${e(x.excerpt)}</p>`;let body;if(x.kind==='story')body=`${heading}<img class="detail-image" src="assets/${e(x.image)}" alt="Illustrative career story"><div class="detail-meta"><span class="avatar">${e(x.initials)}</span>${e(x.author)} · Illustrative story</div>${x.body.map(([h,p])=>`<section class="detail-section"><h3>${e(h)}</h3><p>${e(p)}</p></section>`).join('')}<div class="notice">This is an illustrative story for the concept, not a verified career outcome. Real stories will include dates, context, and verification details.</div><div class="actions"><button class="button primary" data-action="detail" data-id="${x.id==='major'?'interview-task':'design-task'}">Try a small step ${icon('arrow')}</button><button class="button" data-action="save" data-id="${x.id}">${icon('bookmark')}<span data-save-label>${state.saved.includes(x.id)?'Saved':'Save story'}</span></button></div>`;else if(x.kind==='task')body=`${heading}<div class="detail-meta">${icon('clock')}${e(x.tags)}<span>· Simulated task</span></div><div class="notice">A starting point, not a verdict. This exercise helps you experience part of the work; it does not measure job readiness.</div><h3>What you’ll try</h3>${x.steps.map(([h,p],i)=>`<section class="detail-section"><h3><span class="muted">0${i+1} / </span>${e(h)}</h3><p>${e(p)}</p></section>`).join('')}<div class="actions"><button class="button primary" data-action="work" data-id="${x.id}">${state.plans[x.id]?'Continue task':'Start task'} ${icon('arrow')}</button><button class="button" data-action="add-plan" data-id="${x.id}">${icon('plus')}Save to my plan</button></div>`;else {const replies=[...(x.replies||[]),...(Array.isArray(state.answers[id])?state.answers[id]:[])];body=`${heading}<div class="detail-meta"><span class="avatar purple">${e(x.initials||'ME')}</span>${e(x.author)} · ${x.local?'Posted on this device':'Illustrative question'}</div><section class="answers"><h3>${replies.length?`${replies.length} ${replies.length===1?'perspective':'perspectives'}`:'Start the conversation'}</h3>${replies.map(a=>`<article class="answer"><span class="author"><span class="avatar">${e(a.name.slice(0,2).toUpperCase())}</span>${e(a.name)} · ${a.local?'Local reply':'Example perspective'}</span><p>${e(a.text)}</p></article>`).join('')}<form class="answer-form" data-id="${e(id)}"><div class="form-field"><label for="answer-text">Share a thoughtful perspective</label><textarea id="answer-text" name="answer" required minlength="10" maxlength="3000" placeholder="What would you suggest, and why?"></textarea><small>This demo saves your reply on this device only.</small></div><div class="actions"><button class="button primary" type="submit">Post reply ${icon('arrow')}</button></div></form></section>`;}const previous=opener;if(dialog.open){replaceModal(body,x.kind==='story'?'Career story':x.kind==='task'?'Try a role':'Community');opener=previous;}else openModal(body,x.kind==='story'?'Career story':x.kind==='task'?'Try a role':'Community');}
function work(id){const x=item(id);if(!x||x.kind!=='task')return;const p=ensurePlan(state,id);p.notes=Array.isArray(p.notes)?p.notes:['','',''];p.checks=Array.isArray(p.checks)?p.checks:[false,false,false];persist();activeDetail=id;const body=`<p class="eyebrow">${e(x.tags)}</p><h2 id="dialog-title">${e(x.title)}</h2><p class="intro">Take it one step at a time. Your notes stay on this device.</p><form id="task-form" data-id="${id}">${x.steps.map(([title,text],i)=>`<section class="step"><div class="step-heading"><input type="checkbox" name="check-${i}" id="check-${i}" ${p.checks[i]?'checked':''} aria-label="Mark step ${i+1} explored"><div><label for="check-${i}"><h3>${i+1}. ${e(title)}</h3></label><p>${e(text)}</p></div></div><textarea name="note-${i}" aria-label="Notes for step ${i+1}" placeholder="Your thoughts, in your own words..." maxlength="5000">${e(p.notes[i]||'')}</textarea></section>`).join('')}<section class="reflection"><h3>A moment to reflect</h3><p>What did you enjoy? What felt difficult? Would you like to explore more, adjust your direction, or stop here?</p><textarea name="reflection" aria-label="Your reflection" maxlength="5000" placeholder="There’s no right answer. What did you learn about yourself?">${e(p.reflection||'')}</textarea></section><p class="small muted" id="task-save-status" role="status" style="margin-top:13px">${p.complete?'Completed — you can still edit your reflection.':'Changes are saved as you go.'}</p><p class="form-error" id="task-error" role="alert"></p><div class="actions"><button class="button primary" type="submit">${p.complete?'Save reflection':'Complete & reflect'} ${icon('check')}</button><button class="button" type="button" data-action="pause">Save & come back later</button></div></form>`;dialog.open?replaceModal(body,'Your career tryout'):openModal(body,'Your career tryout');shell();}
function captureTask(form){const p=ensurePlan(state,form.dataset.id),fd=new FormData(form);p.notes=[0,1,2].map(i=>String(fd.get('note-'+i)||''));p.checks=[0,1,2].map(i=>fd.has('check-'+i));const nextReflection=String(fd.get('reflection')||'');p.reflection=nextReflection;if(!p.checks.every(Boolean)||p.reflection.trim().length<10)p.complete=false;persist();}
function composer(preview=false){const d=state.draft;activeDetail='compose';const body=preview?`<p class="eyebrow">Review before sharing</p><h2 id="dialog-title">Here’s what people would see.</h2><div class="review-block"><span class="small muted">${d.anonymous?'Anonymous explorer':e(state.name)} · ${e(d.space||'design')}</span><h3 style="margin-top:15px">${e(d.title)}</h3><p>${e(d.body)}</p></div><div class="notice">Prototype only: this question will be stored in this browser’s demo community, not sent to other people.</div><div class="actions"><button class="button primary" data-action="publish">Post locally ${icon('arrow')}</button><button class="button" data-action="compose">${icon('back')}Keep editing</button></div>`:`<p class="eyebrow">A good question is a good beginning</p><h2 id="dialog-title">What’s on your mind?</h2><p class="intro">A little context helps people give you a useful answer.</p><form id="compose-form"><div class="form-field"><label for="post-title">Your question</label><input name="title" id="post-title" required minlength="10" maxlength="160" value="${e(d.title||'')}" placeholder="What would you like to figure out?"><small>10–160 characters. Keep it specific.</small></div><div class="form-field"><label for="post-body">A little background</label><textarea id="post-body" name="body" required minlength="20" maxlength="4000" placeholder="Where are you starting from? What have you tried? What help would be useful?">${e(d.body||'')}</textarea></div><div class="form-field"><label for="post-space">Related direction</label><select id="post-space" name="space">${[['design','Product design'],['data','Data & insights'],['research','User research']].map(([id,label])=>`<option value="${id}" ${d.space===id?'selected':''}>${label}</option>`).join('')}</select></div><label class="check-row"><input type="checkbox" name="anonymous" ${d.anonymous?'checked':''}>Show as Anonymous explorer</label><div class="notice">Only the information shown in your preview is included. Avoid private contact details or sensitive workplace information. Drafts are kept on this device.</div><p class="form-error" id="compose-error" role="alert"></p><div class="actions"><button class="button primary" type="submit">Preview question ${icon('arrow')}</button><button class="button" type="button" data-action="close">Save draft & close</button></div></form>`;dialog.open?replaceModal(body,'Ask the community'):openModal(body,'Ask the community');}
function captureDraft(form){const f=new FormData(form);state.draft={title:String(f.get('title')||''),body:String(f.get('body')||''),space:String(f.get('space')||'design'),anonymous:f.has('anonymous')};persist();}
function settings(){openModal(`<h2 id="dialog-title">Make this space yours.</h2><p class="intro">Your exploration is stored in this browser. No account or cloud sync is connected in this preview.</p><form id="settings-form"><div class="form-field"><label for="display-name">Display name</label><input id="display-name" name="name" value="${e(state.name)}" maxlength="40" required></div><div class="actions"><button class="button primary" type="submit">Save name</button></div></form><div class="divider"></div><h3>Your data, your choice.</h3><div class="settings-actions"><button class="button" data-action="clear-resume">Clear saved resume</button><button class="button" data-action="export">${icon('download')}Export my notes, posts & saved items</button><button class="button danger" data-action="reset-review">${icon('trash')}Reset this preview</button></div><div class="notice">An export includes your local drafts and task notes. Keep the file somewhere private.</div>`,'Settings & your data');}
function guide(){activeDetail='guide';openModal(`<p class="eyebrow">A little guidance</p><h2 id="dialog-title">Start with what matters to you.</h2><p class="intro">Tell us what you’d like to try. We’ll point you toward a small exercise in this preview.</p><form class="guide-form"><label for="guide-text" class="small">What are you curious about?</label><textarea id="guide-text" name="question" required maxlength="1500" placeholder="I enjoy creative work, but I’m not sure where to start..." style="margin-top:10px"></textarea><div class="actions"><button class="button primary">Explore a small step ${icon('arrow')}</button></div></form><div id="guide-output" aria-live="polite"></div><div class="notice">Prototype guide · Uses simple topic matching, not a connected AI model. No employment predictions or personal assessments.</div>`,'Your exploration');}
function showGuide(question){const q=question.toLowerCase();let id=/data|number|analy|spreadsheet/.test(q)?'data-task':/research|listen|interview|psycholog/.test(q)?'interview-task':/design|creativ|product|architect|draw/.test(q)?'design-task':null;const x=item(id);document.querySelector('#guide-output').innerHTML=x?`<div class="guide-result"><h3>Here’s one way to explore.</h3><p>You mentioned a topic related to ${e(x.space)}. This short, simulated task lets you try part of the work and reflect on how it feels.</p><button class="button" data-action="detail" data-id="${x.id}">${e(x.title)} ${icon('arrow')}</button><p class="small" style="margin-top:13px">Source: this preview’s task library. A suggestion, not a judgment of fit.</p></div>`:`<div class="guide-result"><h3>Let’s keep the question open.</h3><p>This preview only has tasks in product design, research, and data. We don’t have enough information to recommend another direction. You can ask the community or browse the available exercises.</p><button class="button" data-action="compose">Shape a question ${icon('arrow')}</button></div>`;}
function clearFilters(){kind='all';query='';space='all';state.stage='all';limit=5;persist();shell();}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;switch(action){case 'close':closeModal();break;case 'detail':detail(id);break;case 'work':work(id);break;case 'save':{const saved=toggleSaved(state,id);persist();shell();if(dialog.open){dialog.querySelectorAll('[data-save-label]').forEach(n=>n.textContent=saved?'Saved':'Save story');}notify(saved?'Saved to your collection.':'Removed from your collection.');break;}case 'filter':kind=id;limit=5;shell();break;case 'stage':state.stage=state.stage===id?'all':id;persist();limit=5;shell();break;case 'space':space=space===id?'all':id;kind='all';query='';limit=5;if(page==='plan'||page==='saved'){page='discover';location.hash='/discover';}shell();break;case 'more':limit+=6;document.querySelector('#results').innerHTML=results();break;case 'clear':clearFilters();break;case 'discover':location.hash='/discover';clearFilters();break;case 'tasks':page='discover';kind='task';query='';space='all';state.stage='all';persist();location.hash='/discover';shell();break;case 'add-plan':ensurePlan(state,id);persist();shell();target.textContent='Added to my plan';notify('A small step, saved to My plan.');break;case 'remove-plan':{const previous=state.plans[id];delete state.plans[id];persist();shell();notify('Removed from your plan.',()=>{state.plans[id]=previous;persist();shell();notify('Restored to your plan.');});break;}case 'undo':if(undoAction)undoAction();break;case 'pause':captureTask(document.querySelector('#task-form'));closeModal();shell();notify('Your progress is saved on this device.');break;case 'compose':composer();break;case 'publish':{const d=state.draft;if(!d.title||d.title.trim().length<10||!d.body||d.body.trim().length<20){composer();return;}state.posts.unshift({id:'local-'+crypto.randomUUID(),kind:'question',stage:'both',space:d.space,title:d.title.trim(),excerpt:d.body.trim(),author:d.anonymous?'Anonymous explorer':state.name,initials:d.anonymous?'AE':state.name.slice(0,2).toUpperCase(),tags:'Your local question',local:true,replies:[]});state.draft={};persist();closeModal();page='community';kind='all';query='';space='all';location.hash='/community';shell();notify('Posted in this browser’s demo community.');break;}case 'settings':settings();break;case 'guide':guide();break;case 'export':{const blob=new Blob([JSON.stringify({product:'find yourjob',exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='find-yourjob-my-exploration.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Your exploration export is ready.');break;}case 'reset-review':replaceModal(`<h2 id="dialog-title">Start fresh?</h2><p class="intro">This permanently clears your resume, preferences, saved roles, study plans, submissions, profile, and community drafts from this browser. It also disconnects the local PayPal Sandbox session.</p><div class="actions"><button class="button danger" data-action="reset">Reset local data</button><button class="button" data-action="close">Keep my data</button></div>`,'Your data');break;case 'clear-resume':{try{localStorage.removeItem('fyj-resume-profile-v1');window.dispatchEvent(new Event('fyj:clear-resume'));notify('Saved resume cleared.')}catch{notify('Could not clear the saved resume.')}break;}case 'reset':resetPreview(target);break;case 'about':openModal(`<h2 id="dialog-title">A place to explore what’s next.</h2><p class="intro">find yourjob is about finding work that fits—and learning more about yourself along the way.</p><section class="detail-section"><h3>What you can do here</h3><p>Explore sample stories and questions, save ideas, draft a question, add a local reply, and complete practical career tryouts. Your changes stay in this browser.</p></section><section class="detail-section"><h3>What’s still a concept</h3><p>All people, stories, and images are illustrative. There is no live community, connected AI, account sync, payment, or verified career advice. Future releases need real contributors and appropriate backend services.</p></section><div class="actions"><button class="button" data-action="settings">Settings & your data ${icon('arrow')}</button></div>`,'About this preview');break;}});
document.addEventListener('submit',event=>{const form=event.target;if(form.id==='search-form'){event.preventDefault();query=document.querySelector('#search-input').value.trim();limit=5;shell();}else if(form.id==='compose-form'){event.preventDefault();captureDraft(form);if(state.draft.title.trim().length<10||state.draft.body.trim().length<20){document.querySelector('#compose-error').textContent='Add a question of at least 10 characters and background of at least 20 characters.';return;}composer(true);}else if(form.classList.contains('answer-form')){event.preventDefault();const text=String(new FormData(form).get('answer')||'').trim();if(text.length<10){form.querySelector('textarea').setCustomValidity('Please share at least 10 characters.');form.reportValidity();return;}const id=form.dataset.id;if(!Array.isArray(state.answers[id]))state.answers[id]=[];state.answers[id].push({name:state.name,text,local:true});persist();detail(id);notify('Your reply is saved on this device.');}else if(form.id==='task-form'){event.preventDefault();captureTask(form);const p=state.plans[form.dataset.id];if(!p.checks.every(Boolean)||p.reflection.trim().length<10){document.querySelector('#task-error').textContent='Mark all three steps explored and add a short reflection (at least 10 characters). You can also save and return later.';return;}p.complete=true;persist();closeModal();page='plan';location.hash='/plan';shell();notify('One small step completed. Keep your reflection close.');}else if(form.id==='settings-form'){event.preventDefault();const value=String(new FormData(form).get('name')||'').trim();if(!value)return;state.name=value;persist();closeModal();shell();notify('Your name has been updated.');}else if(form.classList.contains('guide-form')){event.preventDefault();showGuide(String(new FormData(form).get('question')||''));}});
document.addEventListener('input',event=>{const form=event.target.closest('form');if(form?.id==='compose-form')captureDraft(form);if(form?.id==='task-form'){captureTask(form);document.querySelector('#task-save-status').textContent='Progress saved on this device.';}if(form?.classList.contains('answer-form'))event.target.setCustomValidity('');});
document.addEventListener('change',event=>{const form=event.target.closest('form');if(form?.id==='compose-form')captureDraft(form);if(form?.id==='task-form')captureTask(form);});
window.addEventListener('hashchange',()=>{const next=route();if(next!==page){page=next;kind='all';query='';space='all';limit=5;}if(dialog.open)closeModal();shell();window.scrollTo(0,0);});
shell();


function rememberFocus(){const el=document.activeElement;if(!el||!app.contains(el))return;const action=el.dataset.action,id=el.dataset.id,href=el.getAttribute('href');requestAnimationFrame(()=>{if(dialog.open)return;const next=[...app.querySelectorAll('button,a')].find(n=>action?n.dataset.action===action&&n.dataset.id===id:href&&n.getAttribute('href')===href&&n.getClientRects().length);next?.focus({preventScroll:true});});}






const previewDataKeys = [KEY,'fyj-resume-profile-v1','fyj-conversation-v1','fyj-experiments-v3',
  'fyj-exploration-feedback-v1','fyj-preferences-v1','fyj-local-trial-v1',
  'fyj-saved-targets-v1','fyj-study-plans-v1'];
const resetSignal = 'fyj-preview-reset';
window.addEventListener('storage', event => {
  if (event.key === resetSignal && event.newValue) location.reload();
});
async function resetPreview(control) {
  control.disabled = true;
  try {
    const response = await fetch('/api/paypal/reset',{method:'POST',signal:AbortSignal.timeout(8000)});
    if (!response.ok) throw new Error('Could not reset checkout.');
    for (const key of previewDataKeys) localStorage.removeItem(key);
    localStorage.setItem(resetSignal,crypto.randomUUID());
    localStorage.removeItem(resetSignal);
    history.replaceState(null,'','#/discover');
    location.reload();
  } catch {
    control.disabled = false;
    notify('Could not reset the preview. Try again.');
  }
}
